styles:
:root{--mul:#830051;--mul-soft:#f6e9f0;--navy:#152847;--gold:#f0ab00;--ink:#1d2433;--muted:#5f6b7a;--line:#e3e1e6;--line2:#cfcbd3;--bg:#f4f2f5;--card:#ffffff;--soft:#faf8fb;
 --man:#d0021b;--hyb:#e8891c;--auto:#2f6fce;--pain:#c8102e;--prop:#0070c0;--prop-soft:#e8f2fb;--ok:#1f8a4c;--ok-soft:#e6f4ec;
 --O2C:#0c8b86;--FPA:#830051;--R2R:#2f6fce;--Tax:#23823f;--P2P:#d4580f;--CAPEX:#6a4c9c;--Controlling:#c77a0a;--Group:#152847;
 --acc:var(--mul)}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 Inter,"Segoe UI",system-ui,Arial,sans-serif;font-feature-settings:"tnum" 1,"cv11" 1}
button{font:inherit;color:inherit;background:none;border:0;padding:0;cursor:pointer;text-align:left}
button:focus-visible,[tabindex]:focus-visible{outline:2px solid var(--prop);outline-offset:2px}
h1,h2,h3{margin:0;color:var(--navy);letter-spacing:-.01em}
a{color:var(--prop)}
.wrap{max-width:1440px;margin:0 auto;padding:0 24px}
@media(max-width:600px){.wrap{padding:0 16px}}

/* top bar */
.top{position:sticky;top:0;z-index:20;background:rgba(255,255,255,.92);backdrop-filter:blur(8px);border-bottom:1px solid var(--line)}
.top .wrap{display:flex;align-items:center;gap:18px;min-height:58px;flex-wrap:wrap;padding-top:6px;padding-bottom:6px}
.brand{display:flex;align-items:center;gap:10px;font-weight:700;color:var(--navy);font-size:14px}
.brand i{width:12px;height:12px;border-radius:3px;background:var(--mul);display:inline-block}
.brand small{display:block;font-weight:500;color:var(--muted);font-size:11.5px;line-height:1.2}
.tabs{display:flex;gap:2px;background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:3px}
.tabs button{padding:7px 16px;border-radius:8px;font-weight:600;color:var(--muted);display:flex;align-items:center;gap:8px}
.tabs button i{width:9px;height:9px;border-radius:50%;background:var(--c);display:inline-block}
.tabs button.on{background:var(--card);color:var(--navy);box-shadow:0 1px 2px rgba(16,24,40,.12)}
.view{margin-left:auto;display:flex;align-items:center;gap:10px}
.view .lbl{font-size:12px;color:var(--muted)}
.seg{display:flex;border:1px solid var(--line2);border-radius:10px;overflow:hidden}
.seg button{padding:7px 14px;font-weight:600;font-size:13px;color:var(--muted);background:var(--card)}
.seg button+button{border-left:1px solid var(--line2)}
.seg button.on{background:var(--navy);color:#fff}
.seg button.on.cl{background:var(--prop)}
.seg button .dot{display:inline-block;width:8px;height:8px;border-radius:50%;border:2px dashed currentColor;margin-right:6px;vertical-align:0}

/* page */
.page{display:none}
.page.on{display:block}
.hero{padding:24px 0 10px}
.hero .kick{font-size:12.5px;color:var(--muted);font-weight:500;margin-bottom:6px}
.hero h1{font-size:30px;line-height:1.15;font-weight:800;letter-spacing:-.02em}
.hero h1 span{color:var(--acc)}
.aff{margin:12px 0 0;font-size:12.5px;color:var(--ink)}
.aff .lb{display:inline-block;font-size:11px;font-weight:700;color:var(--muted);margin:0 4px 0 14px}.aff .lb:first-child{margin-left:0}.aff .lb.cl{color:var(--prop)}
.aff span[title]{border-bottom:1px dotted var(--line2);cursor:help}
.skwrap{overflow-x:auto;position:relative}
.skm button i.doc{background:#8a94a6;border-color:#8a94a6;border-radius:2px}.skm button i.ai{background:var(--prop);border-color:var(--prop);border-radius:2px}
.pop{position:absolute;width:300px;background:var(--card);border:1px solid var(--line2);border-radius:10px;box-shadow:0 10px 28px rgba(16,24,40,.18);padding:12px 30px 12px 14px;font-size:12.5px;z-index:5}
.pop .x{position:absolute;top:6px;right:6px;width:22px;height:22px;border-radius:50%;background:var(--soft);color:var(--muted);font-size:11px;display:grid;place-items:center}
.pop .t{font-weight:700;color:var(--navy);line-height:1.3}.pop .t span{color:var(--muted);font-weight:400;margin:0 3px}
.pop .w{margin-top:4px}
.pop .why{margin-top:8px;padding:7px 9px;border-radius:7px;background:var(--prop-soft);color:#174e75;border-left:3px solid var(--prop)}.pop .why b{color:var(--prop);display:block;font-size:11px}
.pop .src{margin-top:6px;font-size:11px;color:var(--muted)}
.sk .lk{pointer-events:stroke}
.sk{width:100%;display:block;min-width:720px}
.sk .lk{fill:none;opacity:.38;transition:opacity .12s;cursor:pointer}
.sk .lk:hover,.sk .lk.sel{opacity:.9}
.sk .lk:focus{outline:none;opacity:.9}
.skleg{display:flex;gap:14px;font-size:11.5px;color:var(--muted);align-items:center}
.skleg i{display:inline-block;width:18px;height:8px;border-radius:2px;margin-right:6px;vertical-align:0}
.skleg .doc{background:#8a94a6}.skleg .c2{background:var(--prop)}.skleg .c1{background:repeating-linear-gradient(90deg,var(--prop) 0 5px,transparent 5px 8px)}
.pgs{display:grid;gap:8px}
.pg{border:1px solid var(--line);border-radius:10px;background:var(--card)}
.pg summary{cursor:pointer;list-style:none;display:flex;align-items:center;gap:10px;padding:9px 12px;font-size:13px}
.pg summary::-webkit-details-marker{display:none}
.pg summary b{color:var(--navy)}
.pg summary .fx{font-size:12px;color:var(--prop);margin-left:auto}
.pg summary::before{content:"";width:7px;height:7px;border-right:1.5px solid var(--muted);border-bottom:1.5px solid var(--muted);transform:rotate(-45deg);transition:transform .15s;flex:none}
.pg[open] summary::before{transform:rotate(45deg)}
.pg table{border-top:1px solid var(--line)}
.pg td{padding:6px 12px}
.cnt.pp{background:var(--pain)}
td small.wh{display:block;color:var(--muted);font-size:11px;margin-left:15px}
.fold summary{cursor:pointer;list-style:none;display:flex;align-items:baseline;gap:14px;flex-wrap:wrap}
.fold summary::-webkit-details-marker{display:none}
.fold summary p{margin:0;font-size:12.5px;color:var(--muted)}
.fold summary::after{content:"Show";margin-left:auto;font-size:12px;font-weight:600;color:var(--prop);border:1px solid #bcd7ee;border-radius:999px;padding:2px 10px}
.fold[open] summary::after{content:"Hide"}
.fold[open] summary{margin-bottom:12px}
.cnt{display:inline-block;font-size:11px;font-weight:700;border-radius:999px;padding:0 7px;margin-left:6px;background:var(--navy);color:#fff;vertical-align:2px}
.cnt.cl{background:var(--prop)}
.hero .meta{display:flex;flex-wrap:wrap;gap:6px 18px;margin-top:10px;font-size:12.5px;color:var(--muted)}
.hero .meta b{color:var(--ink);font-weight:600}

/* D2P ribbon */
.d2p{margin-top:16px;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:18px 20px 16px}
.d2p .hd{display:flex;align-items:baseline;gap:14px;flex-wrap:wrap;margin-bottom:12px}
.d2p h2{font-size:15px}
.d2p .hd p{margin:0;font-size:12.5px;color:var(--muted)}
.ribbon{display:grid;grid-template-columns:repeat(9,1fr);gap:0;overflow-x:auto}
.stg{position:relative;min-width:96px;height:44px;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:12.5px;color:var(--muted);background:var(--soft);clip-path:polygon(0 0,calc(100% - 14px) 0,100% 50%,calc(100% - 14px) 100%,0 100%,14px 50%);margin-right:-10px;border:0}
.stg:first-child{clip-path:polygon(0 0,calc(100% - 14px) 0,100% 50%,calc(100% - 14px) 100%,0 100%)}
.stg.core{background:var(--acc);color:#fff}
.stg.touch{background:color-mix(in srgb,var(--acc) 22%,#fff);color:var(--navy)}
.stg.new{background:var(--prop-soft);color:var(--prop);background-image:repeating-linear-gradient(135deg,transparent 0 6px,rgba(0,112,192,.12) 6px 8px)}
.stg .n{position:absolute;left:22px;top:5px;font-size:9.5px;font-weight:600;opacity:.75}
.rleg{display:flex;flex-wrap:wrap;gap:6px 18px;margin-top:12px;font-size:12px;color:var(--muted)}
.rleg i{display:inline-block;width:14px;height:10px;border-radius:2px;vertical-align:-1px;margin-right:6px}
.rleg .core i{background:var(--acc)}.rleg .touch i{background:color-mix(in srgb,var(--acc) 22%,#fff)}.rleg .new i{background:var(--prop-soft);border:1px dashed var(--prop)}.rleg .none i{background:var(--soft);border:1px solid var(--line)}
.notes{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:10px;margin-top:14px}
.note{border:1px solid var(--line);border-left:4px solid var(--acc);border-radius:8px;padding:9px 12px;font-size:12.5px;background:var(--card)}
.note.touch{border-left-color:color-mix(in srgb,var(--acc) 45%,#fff)}
.note.new{border-left-color:var(--prop);border-style:dashed;border-left-style:solid;background:var(--prop-soft)}
.note b{display:block;color:var(--navy);font-size:12.5px;margin-bottom:2px}
.note.new b{color:var(--prop)}
.note small{display:block;color:var(--muted);font-size:11px;margin-top:3px}

/* stats */
.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-top:16px}
.stat{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:12px 14px}
.stat span{font-size:12px;color:var(--muted);display:block}
.stat b{display:block;font-size:24px;line-height:1.15;color:var(--navy);font-weight:700;margin-top:2px}
.stat small{display:block;font-size:11.5px;color:var(--muted);margin-top:2px}
.stat.cl b{color:var(--prop)}
.stat .delta{color:var(--ok);font-weight:600}
.mix{display:flex;height:8px;border-radius:5px;overflow:hidden;background:var(--line);margin:8px 0 6px}
.mix i{display:block;height:100%}
.mixl{display:flex;gap:10px;font-size:11.5px;color:var(--muted);flex-wrap:wrap}
.mixl i{display:inline-block;width:8px;height:8px;border-radius:2px;margin-right:4px}

/* sections */
.sec{scroll-margin-top:72px;margin-top:22px;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:18px 20px}
.sec .hd{display:flex;align-items:baseline;gap:14px;flex-wrap:wrap;margin-bottom:12px}
.sec h2{font-size:16px}
.sec .hd p{margin:0;font-size:12.5px;color:var(--muted)}
.sec .hd .right{margin-left:auto;display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.sec.cl{border-color:#bcd7ee;border-top:3px solid var(--prop)}
.sec.cl h2{color:var(--prop)}
.pill-cl{display:inline-flex;align-items:center;gap:6px;font-size:11px;font-weight:700;color:var(--prop);border:1px dashed var(--prop);border-radius:999px;padding:1px 8px;background:var(--prop-soft);vertical-align:2px}

/* map */
.tool{display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.fbtns{display:flex;gap:4px;background:var(--bg);border:1px solid var(--line);border-radius:9px;padding:3px;flex-wrap:wrap}
.fbtns button{padding:5px 11px;border-radius:7px;font-size:12.5px;font-weight:600;color:var(--muted);display:flex;align-items:center;gap:6px}
.fbtns button i{width:9px;height:9px;border-radius:2px;display:inline-block;border:2px solid var(--c);background:transparent}
.fbtns button.pp i{border-radius:50%;background:var(--pain);border-color:var(--pain)}
.fbtns button.on{background:var(--card);color:var(--navy);box-shadow:0 1px 2px rgba(16,24,40,.12)}
.zoom{display:flex;gap:4px}
.zoom button{border:1px solid var(--line);border-radius:7px;padding:4px 10px;font-size:12.5px;background:var(--card);font-weight:600}
.zoom .exp{background:var(--navy);color:#fff;border-color:var(--navy)}.zoom .exp .c{display:none}
.sec.full{position:fixed;inset:0;z-index:40;margin:0;border-radius:0;border:0;overflow:auto;padding:14px 20px}
.sec.full .scroll{max-height:none;height:calc(100vh - 150px)}
.sec.full .zoom .exp .o{display:none}.sec.full .zoom .exp .c{display:inline}
.sec.full .asisnote{display:none}
body.nos{overflow:hidden}
.leg{display:flex;flex-wrap:wrap;gap:6px 16px;font-size:11.5px;color:var(--muted);margin:10px 0 8px;align-items:center}
.leg svg{vertical-align:middle;margin-right:4px}
.maprow{position:relative}
.scroll{overflow:auto;border:1px solid var(--line);border-radius:10px;background:#fbfbfc;max-height:84vh;min-height:420px}
.scroll svg{display:block}
.drawer{position:absolute;top:12px;right:12px;width:min(360px,calc(100% - 24px));max-height:calc(100% - 24px);display:none;background:var(--card);border:1px solid var(--line2);border-radius:12px;box-shadow:0 12px 32px rgba(16,24,40,.18);z-index:3}
.drawer.on{display:block}
.drawer .x{position:absolute;top:8px;right:8px;width:26px;height:26px;border-radius:50%;background:var(--soft);color:var(--muted);font-size:12px;display:grid;place-items:center;z-index:1}
.drawer .x:hover{background:var(--line)}
.det{padding:14px 34px 14px 14px;font-size:13px;max-height:calc(84vh - 24px);overflow:auto}
.det h3{margin:0 0 4px;font-size:15px}
.det dl{display:grid;gap:8px;margin:12px 0 0}
.det dt{font-size:11.5px;color:var(--muted)}.det dd{margin:0}
.det .none{color:var(--muted);margin:0}
.own{display:inline-flex;align-items:center;gap:5px;font-weight:600;color:var(--ink);margin-right:10px}
.own i{width:8px;height:8px;border-radius:50%}
.ppl{color:#8a1c1c;background:#fdecec;border-left:3px solid var(--pain);padding:6px 8px;border-radius:4px;margin:2px 0}
.opl{color:var(--prop);border:1px dashed var(--prop);padding:6px 8px;border-radius:6px;margin:2px 0;background:var(--prop-soft)}
.mapsvg .nd{cursor:pointer}
.mapsvg .nd:hover rect.b,.mapsvg .nd:focus rect.b{stroke:var(--navy);stroke-width:2.2}
.mapsvg .nd.sel rect.b{stroke:var(--navy);stroke-width:2.6}
.mapsvg .opn:hover path.b,.mapsvg .opn.sel path.b{stroke:var(--navy);stroke-width:2.4}
.dtab{width:100%;border-collapse:collapse;font-size:12.5px}.dtab th{text-align:left;font-size:11.5px;color:var(--muted);font-weight:600;padding:6px 10px;border-bottom:1px solid var(--line2)}.dtab td{padding:8px 10px;border-bottom:1px solid var(--line);vertical-align:top}.dtab td b{color:var(--navy)}.dtab .q{color:#5b2a7a;font-weight:700}.dtab .ex{color:var(--muted);font-style:italic;font-size:12px}
.flows{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.flows span{border:1px solid var(--line2);border-radius:999px;padding:4px 12px;font-size:12px;color:var(--muted);background:var(--card)}.flows span.on{background:var(--acc);border-color:var(--acc);color:#fff;font-weight:600}
.mapsvg .nd:focus,.mapsvg .opn:focus{outline:none}
.asisnote{font-size:12px;color:var(--muted);margin:8px 0 0}

/* handoffs */
.hgrid{display:grid;grid-template-columns:200px 1fr 1fr;border-top:1px solid var(--line)}
.hgrid>div{padding:10px 12px;border-bottom:1px solid var(--line);font-size:12.5px;min-width:0}
.hgrid .h{font-weight:700;color:var(--navy);background:var(--soft);font-size:12px}
.hgrid .h.cl{color:var(--prop)}
.hgrid .area b{display:block;color:var(--navy)}
.hgrid .area small{color:var(--muted);display:block;font-size:11.5px;margin-top:2px}
.hgrid .cnt{display:inline-block;font-size:11px;font-weight:700;border-radius:999px;padding:0 7px;margin-left:6px;background:var(--navy);color:#fff}
.hgrid .cnt.cl{background:var(--prop)}
.hgrid .col{display:flex;flex-wrap:wrap;gap:5px;align-content:flex-start}
.hgrid .col.cl{background:#f7fbfe}
@media(max-width:800px){.hgrid{grid-template-columns:1fr}.hgrid .h:not(:first-child){display:none}.hgrid .area{background:var(--soft)}}
.ho{display:inline-flex;align-items:center;gap:5px;border:1.3px solid var(--pc);border-radius:999px;padding:2px 9px 2px 7px;font-size:11.5px;font-weight:600;color:var(--pc);background:var(--card);max-width:100%;line-height:1.3}
.ho .dir{font-weight:800;font-size:11px;opacity:.85}
.ho .w{font-weight:400;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:260px;flex:0 1 auto;min-width:0}
.ho.c1{border-style:dashed;--pc:var(--prop)}
.ho.c2{--pc:var(--prop);background:var(--prop-soft)}
.ho:hover,.ho.sel{box-shadow:0 0 0 3px color-mix(in srgb,var(--pc) 18%,transparent)}
.hnote{margin:10px 0 0;font-size:12.5px;color:var(--muted);min-height:20px;border-top:1px dashed var(--line);padding-top:8px}
.hnote b{color:var(--navy)}
.hsum{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px;margin-bottom:14px}
.hsum div{border:1px solid var(--line);border-radius:10px;padding:10px 12px;font-size:12px;color:var(--muted)}
.hsum b{display:block;font-size:22px;color:var(--navy);line-height:1.15}
.hsum .cl b{color:var(--prop)}
.hsum div.cl{border-color:#bcd7ee;background:#f7fbfe}
.hleg{display:flex;flex-wrap:wrap;gap:6px 18px;font-size:11.5px;color:var(--muted);margin:0 0 12px;align-items:center}.hleg>span{display:inline-flex;align-items:center;gap:6px}
.hleg .ho{pointer-events:none}

/* tables */
table{width:100%;border-collapse:collapse;font-size:12.5px}
th{text-align:left;font-size:11.5px;color:var(--muted);font-weight:600;padding:8px 10px;border-bottom:1px solid var(--line2);background:var(--soft)}
td{padding:8px 10px;border-bottom:1px solid var(--line);vertical-align:top}
tr:last-child td{border-bottom:0}
td.where b{display:block;color:var(--navy)}
td.where small{color:var(--muted)}
td.fix{color:#174e75}
td.fix.none{color:var(--muted);font-style:italic}
.badge{display:inline-block;font-size:10.5px;font-weight:700;border-radius:4px;padding:1px 6px;color:#fff;background:var(--navy);white-space:nowrap}
.badge.auto{background:var(--auto)}.badge.hyb{background:var(--hyb)}.badge.pi{background:var(--ok)}
.badge.st{background:var(--soft);color:var(--navy);border:1px solid var(--line2)}
.badge.st.done{background:var(--ok-soft);color:var(--ok);border-color:#b6dcc3}
.badge.st.wip{background:#fff5e0;color:#9a5b00;border-color:#f0d49a}
.badge.st.ai{background:var(--prop-soft);color:var(--prop);border-color:#bcd7ee}
.badge.st.fut{background:var(--soft);color:var(--muted)}
.pp-dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--pain);margin-right:7px;vertical-align:1px}
.tbl-note{font-size:12px;color:var(--muted);margin:10px 0 0}
.tscroll{overflow-x:auto}

/* opportunities */
.ogrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:10px}
.opp{border:1px solid #bcd7ee;border-radius:10px;padding:10px 12px;background:#f7fbfe}
.opp summary{cursor:pointer;list-style:none;display:flex;gap:8px;align-items:flex-start}
.opp summary::-webkit-details-marker{display:none}
.opp summary b{color:var(--navy);font-size:13px;line-height:1.35;flex:1}
.opp .wh{font-size:11.5px;color:var(--muted);margin:3px 0 0 0}
.opp p{margin:8px 0 0;font-size:12.5px;color:var(--ink)}

/* kpis */
.kgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px}
.kpi{border:1px solid var(--line);border-left:4px solid var(--acc);border-radius:10px;padding:10px 12px}
.kpi b{display:block;color:var(--navy);font-size:13.5px}
.kpi span{display:block;font-size:12px;color:var(--muted)}
.kpi small{display:block;font-size:11.5px;color:var(--acc);font-weight:600;margin-top:4px}
.ctl{margin:12px 0 0;font-size:12.5px}
.ctl b{color:var(--navy)}
.fn{font-size:11.5px;color:var(--muted);margin:6px 0 0}

footer{padding:26px 0 40px;font-size:12px;color:var(--muted)}
footer p{margin:4px 0;max-width:900px}
.hide{display:none!important}
@media print{.top{position:static}.scroll{max-height:none}.det{display:none}.maprow{grid-template-columns:1fr}}

/* story */
.story{border-top:4px solid var(--acc)}
.story .hd p b{color:var(--navy)}
.hp{display:flex;align-items:stretch;overflow-x:auto;padding:12px 4px 4px 12px;gap:0}
.hn{position:relative;flex:1 1 0;min-width:94px;border:1.5px solid var(--gc);border-radius:10px;background:color-mix(in srgb,var(--gc) 8%,#fff);padding:11px 8px 9px 10px;margin-right:20px;display:flex;flex-direction:column;gap:3px}
.hn:last-child{margin-right:0}
.hn:not(:last-child)::after{content:"";position:absolute;right:-19px;top:50%;width:17px;height:0;border-top:2.5px solid var(--navy);transform:translateY(-50%)}
